// core/session/transcript.hpp — lib/transcript.js TranscriptTail, ported: the incremental reader of a Claude
// Code transcript (<configdir>/projects/<slug>/<sid>.jsonl) that keeps the few facts the sidebar shows.
// PURE: the caller reads the file (only the bytes appended since its last read) and feeds them in; nothing
// here opens anything. Checked against core/test/fixtures/session/transcript.json (generated by running
// lib/transcript.js over synthetic transcripts).
//
// The JS `poll()` is: stat; a file that shrank starts over (offset 0, rest '', a new decoder); read
// [offset, size); decode as UTF-8 through a StringDecoder; split on '\n'; keep the unfinished last line for
// the next poll; ingest each whole line. Here that is `restart()` + `feed(bytes)` — the caller keeps the
// offset and calls restart() when the file is shorter than it.
#pragma once
#include "replay.hpp"          // Utf8Decoder
#include "../third_party/nlohmann/json.hpp"
#include <cstdint>
#include <optional>
#include <string>
#include <utility>
#include <vector>

namespace deck { namespace session {

// One piece of background work a session started and has not finished (TranscriptTail.background()).
struct BackgroundWork {
  std::string id;
  std::string kind;                       // shell | workflow | task | agent | monitor | cron | wakeup
  std::optional<std::string> label;
  double at = 0;                          // ms epoch it was launched
  std::optional<double> until;            // ms epoch it ends by itself, when it does
  bool recurring = false;
};

// What collectMeta reads off a tile's tail, as plain values (null = std::nullopt, as the JS fields are null).
struct TailFacts {
  std::optional<std::string> title;       // customTitle || aiTitle || null
  std::optional<std::string> lastText, lastRole, lastAt, lastAssistantAt, lastModel, lastEffort;
  std::optional<double> lastContextTokens;
  bool ultracode = false;
  std::optional<double> ultracodeAt;
  std::optional<std::string> cwd;
  // the newest prompt a PERSON sent: "pause" | "resume" | "other", and when (ms) - lib/pause.js reads it
  std::optional<std::string> lastPromptKind;
  std::optional<double> lastPromptAt;
  // TranscriptTail.ultracodeSince(since)
  bool ultracodeSince(double since) const { return ultracode && (!(since != 0) || !ultracodeAt || *ultracodeAt >= since); }
};

class TranscriptTail {
 public:
  // Bytes appended to the file since the last feed. `now` is Date.now(): a record with no timestamp is
  // stamped with it (background work only). Returns how many whole lines were ingested.
  int feed(const char* bytes, size_t n, double now);
  void restart();                         // the file shrank: read it again from the top (the facts already learned stay, as in the JS)
  void ingest(const std::string& line, double now);   // one whole line, without its '\n'

  const TailFacts& facts() const { return f_; }
  std::optional<std::string> aiTitle, customTitle;
  // Background work started at or after `since` (ms) that has not ended by `now`.
  std::vector<BackgroundWork> background(double since, double now) const;

 private:
  struct Bg { std::string kind; std::optional<std::string> label; double at; std::optional<double> until; bool recurring; };
  template <class V> struct OrderedMap {      // a JavaScript Map: insertion order, set() on a key keeps its place
    std::vector<std::pair<std::string, V>> items;
    V* find(const std::string& k) { for (auto& kv : items) if (kv.first == k) return &kv.second; return nullptr; }
    bool has(const std::string& k) const { for (const auto& kv : items) if (kv.first == k) return true; return false; }
    void set(const std::string& k, V v) { if (V* p = find(k)) *p = std::move(v); else items.emplace_back(k, std::move(v)); }
    void erase(const std::string& k) { for (size_t i = 0; i < items.size(); i++) if (items[i].first == k) { items.erase(items.begin() + (long long)i); return; } }
  };
  void noteBackground(const nlohmann::json& rec, double now);
  void endNotified(const std::string& s);
  void setUltracode(bool on, const nlohmann::json& rec);

  TailFacts f_;
  Utf8Decoder decoder_;
  std::string rest_;
  OrderedMap<Bg> bg_;                                      // task id -> work still running
  OrderedMap<std::optional<std::string>> uses_;            // tool_use id -> label
  OrderedMap<std::optional<std::string>> agents_;          // agent id -> label
};

// lib/transcript.js promptKind / humanPromptText: a prompt's kind ("pause" / "resume" / "other"), and the text of a record
// that is a prompt a person sent (nullopt: it is not one)
std::string promptKind(const std::string& text);
std::optional<std::string> humanPromptText(const nlohmann::json& rec);

// lib/transcript.js cronOnceAt: when a one-shot session cron "M H DoM Mon *" fires (local time), at or after
// `from`; nullopt when the expression is not four plain numbers and a fifth field.
std::optional<double> cronOnceAt(const std::string& expr, double from);

}}  // namespace deck::session
